package bidi

import (
	"bufio"
	"compress/gzip"
	"fmt"
	"os"
	"strings"
	"testing"
)

// goldenFile holds vectors produced by the JTOpen BidiShape implementation,
// generated by gen/ShapeGolden.java (mode "golden"). Line format, tab separated:
//
//	id, inAttr chars, outAttr chars, arabic option chars, input hex, output hex | EXC:<exception>
const goldenFile = "testdata/shape_golden.txt.gz"

func decodeUnits(t *testing.T, hexs string) []uint16 {
	t.Helper()
	if len(hexs)%4 != 0 {
		t.Fatalf("hex length %d is not a multiple of 4", len(hexs))
	}
	out := make([]uint16, len(hexs)/4)
	for i := range out {
		var v uint16
		if _, err := fmt.Sscanf(hexs[i*4:i*4+4], "%04X", &v); err != nil {
			t.Fatalf("bad hex %q: %v", hexs[i*4:i*4+4], err)
		}
		out[i] = v
	}
	return out
}

func encodeUnits(units []uint16) string {
	var sb strings.Builder
	for _, u := range units {
		fmt.Fprintf(&sb, "%04X", u)
	}
	return sb.String()
}

func charsOf(s string) []uint16 {
	out := make([]uint16, len(s))
	for i := 0; i < len(s); i++ {
		out[i] = uint16(s[i])
	}
	return out
}

// runShape calls Shape and reports a panic (the Java equivalent of a RuntimeException).
func runShape(in, out *BidiFlagSet, text []uint16, opts *ArabicOptionSet) (res []uint16, panicked bool) {
	defer func() {
		if recover() != nil {
			panicked = true
		}
	}()
	var sh BidiShape
	res = sh.Shape(in, out, text, opts)
	return res, false
}

func TestShapeGolden(t *testing.T) {
	f, err := os.Open(goldenFile)
	if err != nil {
		t.Fatalf("open golden file: %v", err)
	}
	defer f.Close()
	zr, err := gzip.NewReader(f)
	if err != nil {
		t.Fatalf("gzip: %v", err)
	}
	defer zr.Close()

	sc := bufio.NewScanner(zr)
	sc.Buffer(make([]byte, 1<<20), 1<<24)

	total, changed, panics := 0, 0, 0
	for sc.Scan() {
		line := sc.Text()
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		fields := strings.Split(line, "\t")
		if len(fields) != 6 {
			t.Fatalf("vector %d: want 6 fields, got %d", total, len(fields))
		}
		id := fields[0]
		inAttr := NewBidiFlagSetFromChars(charsOf(fields[1]))
		outAttr := NewBidiFlagSetFromChars(charsOf(fields[2]))
		opts := NewArabicOptionSetFromChars(charsOf(fields[3]))
		input := decodeUnits(t, fields[4])
		want := fields[5]

		got, panicked := runShape(inAttr, outAttr, append([]uint16(nil), input...), opts)
		if strings.HasPrefix(want, "EXC:") {
			if !panicked {
				t.Errorf("vector %s (%s %s %s): expected panic (%s), got %s",
					id, fields[1], fields[2], fields[3], want, encodeUnits(got))
			}
			panics++
		} else if panicked {
			t.Errorf("vector %s (%s %s %s): unexpected panic, want %s", id, fields[1], fields[2], fields[3], want)
		} else if g := encodeUnits(got); g != want {
			t.Errorf("vector %s (%s %s %s)\n input %s\n  got %s\n want %s",
				id, fields[1], fields[2], fields[3], fields[4], g, want)
		}
		if !panicked && encodeUnits(input) != encodeUnits(got) {
			changed++
		}
		total++
	}
	if err := sc.Err(); err != nil {
		t.Fatalf("reading golden file: %v", err)
	}
	if total < 4000 {
		t.Fatalf("only %d golden vectors, expected at least 4000", total)
	}
	if changed < total/4 {
		t.Errorf("only %d of %d vectors changed the text; the vectors look degenerate", changed, total)
	}
	t.Logf("golden vectors: %d (changed text: %d, exception cases: %d)", total, changed, panics)
}

// The default option set must match the Java default (ArabicOptionSet.DEFAULT).
func TestArabicOptionSetDefaults(t *testing.T) {
	s := NewArabicOptionSet()
	if s.GetLamAlefMode() != LamAlefAuto || s.GetSeenMode() != SeenAuto ||
		s.GetYehHamzaMode() != YehHamzaAuto || s.GetTashkeelMode() != TashkeelAuto {
		t.Fatalf("unexpected defaults: %v %v %v %v", s.GetLamAlefMode(), s.GetSeenMode(),
			s.GetYehHamzaMode(), s.GetTashkeelMode())
	}
}
